package android.content;import java.util.*;public class Intent{private final Map<String,String> extra=new HashMap<>();private String action;public Intent(){}public Intent(Context c,Class<?> type){}public Intent putExtra(String k,String v){extra.put(k,v);return this;}public Intent putExtra(String k,int v){return this;}public String getStringExtra(String k){return extra.get(k);}public Intent setAction(String v){action=v;return this;}public String getAction(){return action;}}
